entries[190168] = { ["name"] = "Krustiger Kriecher", ["text"] = "Wird an Kriegsmeute gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n\"Diese seltene Riesenkrabbe hat ihren Unterwasserunsinn unterbrochen, um die Oberfläche zu erkunden.\"\nHandelsposten" }
entries[190169] = { ["name"] = "Krah", ["text"] = "Wird an Kriegsmeute gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Krächz' älterem (und lauterem) Bruder scheint Eure Gegenwart nichts auszumachen. Im Moment. Ihr solltet wohl besser einige Kekse besorgen.\"\nHandelsposten" }
entries[190170] = { ["name"] = "Jigglesworth sen.", ["text"] = "Schicksalhaft\nWird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Niemand weiß genau, was den Sattel auf diesem einst katzenhaften Freund hält, aber das Haus der Seuchen hat es wohl irgendwie geschafft. Wissenschaft.\"\nErfolg:\nSchicksalsschlachtzüge von Shadowlands" }
