entries[190378] = { ["name"] = "Glyphe 'Spektrallupin'", ["text"] = "Klassen: Schamane\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nÄndert das Erscheinungsbild Eurer Geisterwolfgestalt ab, in der Ihr daraufhin als Spektrallupin erscheint.\nVerkaufspreis:" }
entries[190379] = { ["name"] = "Technik: Glyphe 'Spektrallupin'", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man eine Glyphe 'Spektrallupin' herstellt.\nStellt eine Glyphe 'Spektrallupin' her.\nBenötigt Inschriftenkunde der Schattenlande (100)\nBenötigt Die Erleuchteten\n- Respektvoll\nVerkaufspreis:\nGlyphe 'Spektrallupin'\nKlassen: Schamane\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nÄndert das Erscheinungsbild Eurer Geisterwolfgestalt ab, in der Ihr daraufhin als Spektrallupin erscheint.\nVerkaufspreis:\nBenötigt Dunkles Pergament , Stille Tinte (12), Leuchtende Tinte (20)" }
entries[190380] = { ["name"] = "Glyphe 'Spektralvulpin'", ["text"] = "Klassen: Schamane\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nÄndert das Erscheinungsbild Eurer Geisterwolfgestalt ab, in der Ihr daraufhin als Spektralvulpin erscheint.\nVerkaufspreis:" }
entries[190381] = { ["name"] = "Technik: Glyphe 'Spektralvulpin'", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man eine Glyphe 'Spektralvulpin' herstellt.\nStellt eine Glyphe 'Spektralvulpin' her.\nBenötigt Inschriftenkunde der Schattenlande (100)\nVerkaufspreis:\nGlyphe 'Spektralvulpin'\nKlassen: Schamane\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nÄndert das Erscheinungsbild Eurer Geisterwolfgestalt ab, in der Ihr daraufhin als Spektralvulpin erscheint.\nVerkaufspreis:\nBenötigt Dunkles Pergament , Stille Tinte (12), Leuchtende Tinte (20)" }
entries[190382] = { ["name"] = "Verzerrte Taschendimension", ["text"] = "Wird beim Aufheben gebunden\n\"Ganz egal, wie tief Ihr hineingreift, das Einzige, was Ihr in der Tasche findet, ist sie selbst.\"\n<Zum Öffnen rechtsklicken>\nVerkaufspreis:" }
entries[190384] = { ["name"] = "Ewige Verstärkungsrune", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Erhöht die Beweglichkeit, Intelligenz und Stärke für 1 Stunde um 49 . Verstärkungsrune. (1 Min Abklingzeit)\nBenötigt Die Erleuchteten\n- Ehrfürchtig\n\"Ein geheimnisvolles Werkzeug, das von den Automas geschmiedet wurde und unablässig Energie ausstößt.\"\nVerkaufspreis:" }
