entries[190450] = { ["name"] = "Erweckte Zorneskraft", ["text"] = "Benutzen: Verwandelt erweckte Zorneskraft in 10 Einheiten tobende Zorneskraft.\nHandwerksmaterial\n\"Kann aus verschiedenen Quellen auf den Dracheninseln gewonnen werden, während der Kriegsmodus aktiv ist oder durch Teilnahme an instanziiertem PvP. Kann im Auktionshaus verkauft und erworben werden.\"\nVerkaufspreis:" }
entries[190451] = { ["name"] = "Tobende Zorneskraft", ["text"] = "Benutzen: Verwandelt zehn Einheiten tobende Zorneskraft in erweckte Zorneskraft.\nHandwerksmaterial\n\"Kann aus verschiedenen Quellen auf den Dracheninseln gewonnen werden, während der Kriegsmodus aktiv ist oder durch Teilnahme an instanziiertem PvP. Kann im Auktionshaus verkauft und erworben werden.\"\nVerkaufspreis:" }
entries[190452] = { ["name"] = "Urfluxus", ["text"] = "Handwerksmaterial\n\"Dient zum Entfernen von Unreinheiten aus Metall. Ist bei Schmiedekunsthändlern erhältlich.\"\nVerkaufspreis:" }
entries[190453] = { ["name"] = "Funke der Genialität", ["text"] = "Saison 1 von Dragonflight\nWird beim Aufheben gebunden\nOptionales Handwerksmaterial\n\nGewährt die folgende Eigenschaft: Legt die Anfangsgegenstandsstufe je nach Herstellungsqualität (382 - 395) fest und markiert den Gegenstand als 'Genial gefertigt'.\n\"In der Innovationsmaschine von Valdrakken erschaffen. Durch dieses einzigartige Handwerksmaterial kann ein Gegenstand Wissen verleihen, das jenseits der Fähigkeiten des sterblichen Verstands ist.\"\nVerkaufspreis:" }
entries[190454] = { ["name"] = "Ausgelaugtes urzeitliches Chaos", ["text"] = "Wird beim Aufheben gebunden\n\"Geformt aus ungezügelten Elementen, die von den mächtigsten Bewohnern der Dracheninseln angelockt wurden. War einst ein wesentlicher Bestandteil zur Herstellung von mächtigen Gegenständen und mächtiger Ausrüstung.\"\nVerkaufspreis:" }
entries[190455] = { ["name"] = "Konzentrierter Urfokus", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Kombiniert 10 konzentrierte Urfokusse, um eine konzentrierte urzeitliche Infusion zu erschaffen.\nHandwerksmaterial\n\"Wird verwendet, um ein optionales Reagenz für die Herstellung von mythischer Ausrüstung zu erschaffen.\"\nVerkaufspreis:" }
entries[190456] = { ["name"] = "Eifer des Handwerkers", ["text"] = "Wird beim Aufheben gebunden\nHandwerksmaterial\n\"Dieses Reagenz ist ein Mysterium der Dracheninseln und fügt sich jedes Mal neu zusammen, wenn Ihr Euch mehr Berufswissen aneignet.Es bietet unzählige Verwendungsmöglichkeiten, unter anderem ermöglicht es das Umfertigen von auf den Dracheninseln hergestellter Ausrüstung.\"\nVerkaufspreis:" }
entries[190457] = { ["name"] = "Protopologischer Würfel", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Nimmt das Aussehen eines naszenten Prototyps an. (1 Stunde Abklingzeit)\n\"So fühlt sich Abstraktheit also an.\"" }
