entries[190580] = { ["name"] = "Herzgebundener Lupin", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Vom Moment seiner Schöpfung an hat dieser rudellose Lupin nichts anderes als tiefste Zuneigung und Loyalität für Euch empfunden.\"\nBeruf:\nProtoformsynthese" }
