entries[190765] = { ["name"] = "Iskas Schlundrattenleine", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man eine kolossale Schlundratte beschwört.\nBeschwört Eure riesige Seuchenschlundratte oder gibt sie wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Diese Nagetiere wurden zu Iskas berüchtigten Wächtern, die den Schlund auskundschaften und ihn mit ihrer Seuche überziehen. Wo sie auftreten, folgt nur das Verderben.\"\nBeute von:\nRhuv, Verschlinger des Ruins" }
entries[190766] = { ["name"] = "Schwanz der Spektralschlundratte", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man eine kolossale Schlundratte beschwört.\nBeschwört eure kolossale gespenstergebundene Schlundratte oder gibt sie wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Diese von den Energien gequälter Seelen durchdrungenen Kreaturen haben gespenstische Fähigkeiten entwickelt, wodurch sie ziemlich schwer zu fassen sind.\"\nBeute von:\nSchlundgebundene Vorratstruhe" }
entries[190767] = { ["name"] = "Gepanzerter goldener Pterrordax", ["text"] = "Wird an Kriegsmeute gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n\"Diese bemalten und mit Gold verzierten Pterrordaxe streifen durch Lüfte über der Gruft von Atal'Dazar.\"\nHandelsposten" }
entries[190768] = { ["name"] = "Fraktalchiffre des Zerethaufsehers", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Dieses rätselhafte und unnahbare Konstrukt der Ersten fliegt auf einem anmutigen Strom absoluten geometrischen Wissens.\"\nBeute von:\nDer Kerkermeister\nZone:\nMausoleum der Ersten\nSchwierigkeitsgrad:\nMythisch" }
entries[190769] = { ["name"] = "Instabiles Arkana", ["text"] = "Questgegenstand\n\"Zu einem Edelstein verdichtetes instabiles Arkana. Könnte jeden Moment explodieren... also schüttelt es nicht zu sehr.\"" }
entries[190771] = { ["name"] = "Fraktalchiffre des carzinisierten Zerethhirsches", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Die wenigen, die von diesen mysteriösen Wesen noch verblieben sind, erscheinen unmöglich alt, fast schon zeitlos. Vielleicht wurden sie von den Ersten selbst erschaffen, da noch kein Bauplan gefunden wurde, um sie zu synthetisieren.\"\nQuest:\nLeitmotive" }
entries[190772] = { ["name"] = "Ensemble: Birkenwickel aus dem Alptraum des Erzdruiden", ["text"] = "Legion Remix\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Sammelt die Vorlagen dieses Rüstungssets. Die Vorlagen können nur von Dämonenjägern, Druiden, Mönchen und Schurken verwendet werden." }
entries[190773] = { ["name"] = "Echo des Almanachs", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n\"Eine merkwürdige, rührende Melodie wurde in die Mechanik dieses Geräts gewebt.\"" }
